INSERT INTO `survey_finish` (`SurveyFinishId`, `SurveyFinishDetail`, `SurveyFinishDelta`, `SurveyId`) VALUES
	(1, '<ol><li data-list="ordered"><span class="ql-ui" contenteditable="false"></span>Lokasi survey terletak di daerah pedesaan dengan akses jalan yang kurang baik.</li><li data-list="ordered"><span class="ql-ui" contenteditable="false"></span>Masyarakat setempat memiliki mata pencaharian utama sebagai petani dan nelayan.</li><li data-list="ordered"><span class="ql-ui" contenteditable="false"></span>Fasilitas umum seperti air bersih dan listrik masih terbatas.</li><li data-list="ordered"><span class="ql-ui" contenteditable="false"></span>Masyarakat memiliki persepsi positif tentang program pemerintah untuk meningkatkan kualitas hidup.</li><li data-list="ordered"><span class="ql-ui" contenteditable="false"></span>Masalah utama yang dihadapi masyarakat adalah kurangnya akses ke layanan kesehatan dan pendidikan.</li><li data-list="ordered"><span class="ql-ui" contenteditable="false"></span>Masyarakat berharap adanya peningkatan infrastruktur dan fasilitas umum untuk meningkatkan kualitas hidup.</li></ol><p><br></p><p>Dengan hasil survey lapangan ini, Anda dapat memahami kondisi di lokasi dan membuat rekomendasi yang tepat untuk perbaikan.</p>', '{"ops":[{"insert":"Lokasi survey terletak di daerah pedesaan dengan akses jalan yang kurang baik."},{"attributes":{"list":"ordered"},"insert":"\\n"},{"insert":"Masyarakat setempat memiliki mata pencaharian utama sebagai petani dan nelayan."},{"attributes":{"list":"ordered"},"insert":"\\n"},{"insert":"Fasilitas umum seperti air bersih dan listrik masih terbatas."},{"attributes":{"list":"ordered"},"insert":"\\n"},{"insert":"Masyarakat memiliki persepsi positif tentang program pemerintah untuk meningkatkan kualitas hidup."},{"attributes":{"list":"ordered"},"insert":"\\n"},{"insert":"Masalah utama yang dihadapi masyarakat adalah kurangnya akses ke layanan kesehatan dan pendidikan."},{"attributes":{"list":"ordered"},"insert":"\\n"},{"insert":"Masyarakat berharap adanya peningkatan infrastruktur dan fasilitas umum untuk meningkatkan kualitas hidup."},{"attributes":{"list":"ordered"},"insert":"\\n"},{"insert":"\\nDengan hasil survey lapangan ini, Anda dapat memahami kondisi di lokasi dan membuat rekomendasi yang tepat untuk perbaikan.\\n"}]}', 5),
